SourceCode.Declaration:
using EXT = Microsoft.Dynamics.Integration.Telemetry;

/// <summary>
/// Handler for application insights integration.
/// </summary>
internal class SysTelemetryHelper
{
    static EXT.TelemetryClient handledResult;

}

Method.Source:
/// <summary>
/// Handles the client delegate call from another package
/// </summary>
/// <param name = "_res">EventHandlerResult</param>
[SubscribesTo(classStr(SysGlobalTelemetry), staticDelegateStr(SysGlobalTelemetry, instantiateClient))]
public static void clientInstantiator(EventHandlerResult _res)
{
    _res.result(SysTelemetryHelper::handledResult);
}

/// <summary>
/// Static constructor for the SysTelemetryHelper class.
/// </summary>
static void TypeNew()
{
    str appURI = SysGlobalTelemetry::findAppId();
    
    if(appURI && !Global::isRunningSyncEngine())
    {
        handledResult = SysGlobalTelemetry::newClient(appURI);
    }
}

/// <summary>
/// Flushes the telemetry client on SysUserLog updateLogoutTime.
/// </summary>
/// <param name = "_args">The parameters for the updateLogoutTime method.</param>
[PostHandlerFor(tableStr(SysUserLog), tableStaticMethodStr(SysUserLog, updateLogoutTime)), SuppressBPWarningAttribute('BPParameterNotUsed', 'Event handler must match the signature of the subscribed event.')]
internal static void clientFlush(XppPrePostArgs _args)
{
    SysGlobalTelemetry::clientFlush();
}
